function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function finiteNumber(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function positiveNumber(value: unknown, fallback: number): number {
  const number = finiteNumber(value);
  return number !== null && number > 0 ? number : fallback;
}

function nonNegativeNumber(value: unknown, fallback: number): number {
  const number = finiteNumber(value);
  return number !== null && number >= 0 ? number : fallback;
}

function integer(value: unknown, fallback: number): number {
  const number = finiteNumber(value);
  return number !== null && Number.isInteger(number) ? number : fallback;
}

function stringValue(value: unknown, fallback: string): string {
  return typeof value === "string" && value.trim() !== "" ? value : fallback;
}

function booleanValue(value: unknown, fallback: boolean): boolean {
  return typeof value === "boolean" ? value : fallback;
}

function numberArray(value: unknown, fallback: ReadonlyArray<number>): ReadonlyArray<number> {
  if (!Array.isArray(value)) return fallback;
  const numbers = value.filter((item): item is number => finiteNumber(item) !== null);
  return numbers.length === value.length && numbers.length > 0 ? numbers : fallback;
}

function stringArray(value: unknown, fallback: ReadonlyArray<string>): ReadonlyArray<string> {
  if (!Array.isArray(value)) return fallback;
  return value.every((item) => typeof item === "string") ? (value as string[]) : fallback;
}

function validTimeZone(zone: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: zone }).format(0);
    return true;
  } catch {
    return false;
  }
}

function parseWorkingHours(raw: unknown): WorkingHours {
  const fallback = DEFAULT_SESSION_POLICY.unattended.workingHours;
  if (!isRecord(raw)) return fallback;
  const zone = stringValue(raw.timeZone, fallback.timeZone);
  const days = numberArray(raw.workingDays, fallback.workingDays).filter(
    (day) => Number.isInteger(day) && day >= 1 && day <= 7,
  );
  const start = integer(raw.startMinute, fallback.startMinute);
  const end = integer(raw.endMinute, fallback.endMinute);
  return {
    timeZone: validTimeZone(zone) ? zone : fallback.timeZone,
    workingDays: days.length > 0 ? days : fallback.workingDays,
    startMinute: start >= 0 && start <= 24 * 60 ? start : fallback.startMinute,
    endMinute: end >= 0 && end <= 24 * 60 ? end : fallback.endMinute,
    holidays: stringArray(raw.holidays, fallback.holidays),
  };
}

function parseStepLimits(raw: unknown, fallback: StepLimits): StepLimits {
  if (!isRecord(raw)) return fallback;
  return {
    maxMinutes: positiveNumber(raw.maxMinutes, fallback.maxMinutes),
    maxSteps: positiveNumber(raw.maxSteps, fallback.maxSteps),
  };
}

/**
 * Parse the canonical session-policy document. Unknown or missing fields fall
 * back per field, so a newer or older control service never disables a rule by
 * accident.
 */
export function parseSessionPolicy(payload: unknown): SessionPolicy {
  if (!isRecord(payload)) return DEFAULT_SESSION_POLICY;

  const budgetRaw = isRecord(payload.budget) ? payload.budget : {};
  const unattendedRaw = isRecord(payload.unattended) ? payload.unattended : {};
  const loopRaw = isRecord(payload.loop) ? payload.loop : {};
  const softRaw = isRecord(payload.softLimit) ? payload.softLimit : {};

  const limit =
    finiteNumber(budgetRaw.limitUsd) ??
    finiteNumber(payload.sessionBudgetUsd) ??
    finiteNumber(payload.budgetUsd);
  const spent =
    finiteNumber(budgetRaw.spentUsd) ??
    finiteNumber(payload.spentUsd) ??
    finiteNumber(payload.spendUsd);

  return {
    budget: {
      limitUsd: limit !== null && limit > 0 ? limit : DEFAULT_SESSION_POLICY.budget.limitUsd,
      spentUsd: spent !== null && spent >= 0 ? spent : DEFAULT_SESSION_POLICY.budget.spentUsd,
      warnRatios: numberArray(budgetRaw.warnRatios, DEFAULT_SESSION_POLICY.budget.warnRatios),
      stopRatio: positiveNumber(budgetRaw.stopRatio, DEFAULT_SESSION_POLICY.budget.stopRatio),
    },
    unattended: {
      workingHours: parseWorkingHours(unattendedRaw.workingHours),
      working: parseStepLimits(unattendedRaw.working, DEFAULT_SESSION_POLICY.unattended.working),
      offHours: parseStepLimits(unattendedRaw.offHours, DEFAULT_SESSION_POLICY.unattended.offHours),
    },
    loop: {
      sameToolArgs: positiveNumber(loopRaw.sameToolArgs, DEFAULT_SESSION_POLICY.loop.sameToolArgs),
      sameError: positiveNumber(loopRaw.sameError, DEFAULT_SESSION_POLICY.loop.sameError),
    },
    softLimitRatio: positiveNumber(
      softRaw.ratio ?? payload.softLimitRatio,
      DEFAULT_SESSION_POLICY.softLimitRatio,
    ),
  };
}

/** Build a policy from `GET /api/me` when the session-policy route is absent. */
export function policyFromAllowance(payload: unknown): SessionPolicy {
  if (!isRecord(payload)) return DEFAULT_SESSION_POLICY;
  const limits = isRecord(payload.limits) ? payload.limits : {};
  const limit =
    finiteNumber(payload.effectiveBudgetUsd) ??
    finiteNumber(limits.budgetUsd) ??
    DEFAULT_SESSION_POLICY.budget.limitUsd;
  const spent = nonNegativeNumber(payload.spendUsd, DEFAULT_SESSION_POLICY.budget.spentUsd);
  return {
    ...DEFAULT_SESSION_POLICY,
    budget: {
      ...DEFAULT_SESSION_POLICY.budget,
      limitUsd: limit > 0 ? limit : DEFAULT_SESSION_POLICY.budget.limitUsd,
      spentUsd: spent,
    },
  };
}

/** Working-hours test using the policy's IANA zone, including holidays. */
export function isWorkingTime(hours: WorkingHours, atMs: number): boolean {
  let parts: Intl.DateTimeFormatPart[];
  try {
    parts = new Intl.DateTimeFormat("en-US", {
      timeZone: hours.timeZone,
      weekday: "short",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      hourCycle: "h23",
    }).formatToParts(new Date(atMs));
  } catch {
    return true;
  }
  const pick = (type: Intl.DateTimeFormatPartTypes): string =>
    parts.find((part) => part.type === type)?.value ?? "";
  const weekday = pick("weekday");
  const jsDay = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].indexOf(weekday);
  // ISO weekday (Monday = 1 ... Sunday = 7), matching the control service
  // (`src/watcher/offhours.ts`) and the `workingDays` validation in the API.
  const day = jsDay < 0 ? Number.NaN : jsDay === 0 ? 7 : jsDay;
  const date = `${pick("year")}-${pick("month")}-${pick("day")}`;
  const hour = Number.parseInt(pick("hour"), 10);
  const minute = Number.parseInt(pick("minute"), 10);
  if (!Number.isInteger(day) || day < 1 || !Number.isFinite(hour) || !Number.isFinite(minute)) {
    return true;
  }
  if (hours.holidays.includes(date)) return false;
  if (!hours.workingDays.includes(day)) return false;
  const minutes = hour * 60 + minute;
  return minutes >= hours.startMinute && minutes < hours.endMinute;
}

// ---------------------------------------------------------------------------
// Privacy-safe hashing
// ---------------------------------------------------------------------------

/** FNV-1a, 32 bits. Small, synchronous and enough for loop counts. */
export function hashText(text: string): string {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, "0");
}

/** Stable JSON with sorted keys, so equal arguments always hash equally. */
export function canonicalJson(value: unknown): string {
  const seen = new Set<object>();
  const walk = (node: unknown, depth: number): unknown => {
    if (depth > 8) return "[depth]";
    if (node === null || typeof node !== "object") {
      if (typeof node === "bigint") return `${node.toString()}n`;
      if (typeof node === "function" || typeof node === "symbol") return "[value]";
      if (typeof node === "undefined") return null;
      return node;
    }
    if (seen.has(node)) return "[cycle]";
    seen.add(node);
    if (Array.isArray(node)) return node.map((item) => walk(item, depth + 1));
    const record = node as Record<string, unknown>;
    const result: Record<string, unknown> = {};
    for (const key of Object.keys(record).sort()) {
      result[key] = walk(record[key], depth + 1);
    }
    return result;
  };
  try {
    return JSON.stringify(walk(value, 0)) ?? "null";
  } catch {
    return "null";
  }
}

/** Hash of a tool call: name plus the canonical arguments, never the arguments. */
export function toolSignature(tool: string, args: unknown): string {
  return `${tool}:${hashText(canonicalJson(args).slice(0, 4000))}`;
}

/**
 * A short signature for a failed tool result. It reads the first line only and
 * returns a hash; the output itself is never stored.
 */
export function toolErrorSignature(output: ToolAfterOutput): string | null {
  const metadata = isRecord(output.metadata) ? output.metadata : {};
  const text = typeof output.output === "string" ? output.output : "";
  const looksFailed =
    metadata.error !== undefined ||
    metadata.status === "error" ||
    /^\s*(error|fatal|failed)\b/i.test(text) ||
    /\b(command failed|exited with (code|status) [1-9])\b/i.test(text);
  if (!looksFailed) return null;
  const firstLine = text.split(/\r?\n/, 1)[0] ?? "";
  const normalized = firstLine
    .replace(/[0-9a-f]{8,}/gi, "<id>")
    .replace(/\d+/g, "<n>")
    .trim()
    .slice(0, 300);
  return hashText(normalized === "" ? "tool-error" : normalized);
}

// ---------------------------------------------------------------------------
// Persisted state
// ---------------------------------------------------------------------------

export interface PauseState {
  readonly kind: "unattended" | "loop";
  readonly reason: "time" | "steps" | "tool_args" | "error";
  readonly at: number;
}

export interface SessionState {
  readonly version: 1;
  readonly sessionId: string;
  createdAt: number;
  updatedAt: number;
  lastHumanAt: number;
  stepsSinceHuman: number;
  costUsd: number;
  /** Per assistant message id, so repeated `message.updated` is not summed twice. */
  readonly messageCosts: Record<string, number>;
  /** Insertion order for pruning `messageCosts`; ids only. */
  readonly messageOrder: string[];
  readonly warnFired: number[];
  stopFired: boolean;
  pause: PauseState | null;
  /** Tool signature hash -> count in the current human turn. */
  readonly toolCounts: Record<string, number>;
  /** Error signature hash -> count in the current human turn. */
  readonly errorCounts: Record<string, number>;
  lastSoftCheckAt: number;
  softNoticeShown: boolean;
  lastPolicy: SessionPolicy | null;
  lastPolicyFetchAt: number;
  policyFallbackPosted: boolean;
}

const MAX_MESSAGES = 500;
const MAX_SIGNATURES = 64;

export function sanitizeSessionId(sessionId: string): string {
  const clean = sessionId.replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 80);
  return clean === "" ? "session" : clean;
}

export function sessionStatePath(stateDir: string, sessionId: string): string {
  return join(stateDir, `session-${sanitizeSessionId(sessionId)}-${hashText(sessionId)}.json`);
}

function freshState(sessionId: string, now: number): SessionState {
  return {
    version: 1,
    sessionId,
    createdAt: now,
    updatedAt: now,
    lastHumanAt: now,
    stepsSinceHuman: 0,
    costUsd: 0,
    messageCosts: {},
    messageOrder: [],
    warnFired: [],
    stopFired: false,
    pause: null,
    toolCounts: {},
    errorCounts: {},
    lastSoftCheckAt: 0,
    softNoticeShown: false,
    lastPolicy: null,
    lastPolicyFetchAt: 0,
    policyFallbackPosted: false,
  };
}

/** Narrow a parsed state back to the fields we accept; anything else is dropped. */
function reviveState(raw: unknown, sessionId: string, now: number): SessionState {
  if (!isRecord(raw) || raw.version !== 1 || raw.sessionId !== sessionId) {
    return freshState(sessionId, now);
  }
  const state = freshState(sessionId, now);
  state.createdAt = nonNegativeNumber(raw.createdAt, now);
  state.updatedAt = nonNegativeNumber(raw.updatedAt, now);
  state.lastHumanAt = nonNegativeNumber(raw.lastHumanAt, state.createdAt);
  state.stepsSinceHuman = Math.max(0, integer(raw.stepsSinceHuman, 0));
  state.costUsd = nonNegativeNumber(raw.costUsd, 0);
  state.stopFired = booleanValue(raw.stopFired, false);
  state.lastSoftCheckAt = nonNegativeNumber(raw.lastSoftCheckAt, 0);
  state.softNoticeShown = booleanValue(raw.softNoticeShown, false);
  state.lastPolicyFetchAt = nonNegativeNumber(raw.lastPolicyFetchAt, 0);
  state.policyFallbackPosted = booleanValue(raw.policyFallbackPosted, false);
  if (Array.isArray(raw.warnFired)) {
    for (const ratio of raw.warnFired) {
      if (finiteNumber(ratio) !== null) state.warnFired.push(ratio);
    }
  }
  if (isRecord(raw.messageCosts)) {
    for (const [id, cost] of Object.entries(raw.messageCosts)) {
      const value = finiteNumber(cost);
      if (value !== null && value >= 0) {
        state.messageCosts[id] = value;
        state.messageOrder.push(id);
      }
    }
  }
  if (isRecord(raw.toolCounts)) {
    for (const [signature, count] of Object.entries(raw.toolCounts)) {
      const value = finiteNumber(count);
      if (value !== null) state.toolCounts[signature] = value;
    }
  }
  if (isRecord(raw.errorCounts)) {
    for (const [signature, count] of Object.entries(raw.errorCounts)) {
      const value = finiteNumber(count);
      if (value !== null) state.errorCounts[signature] = value;
    }
  }
  if (isRecord(raw.pause)) {
    const kind = raw.pause.kind;
    const reason = raw.pause.reason;
    if (
      (kind === "unattended" || kind === "loop") &&
      (reason === "time" || reason === "steps" || reason === "tool_args" || reason === "error")
    ) {
      state.pause = { kind, reason, at: nonNegativeNumber(raw.pause.at, now) };
    }
  }
  if (isRecord(raw.lastPolicy)) {
    state.lastPolicy = parseSessionPolicy(raw.lastPolicy);
  }
  return state;
}

/** Keep only the newest `MAX_SIGNATURES` counts, and the newest messages. */
function pruneState(state: SessionState): void {
  const trim = (counts: Record<string, number>): void => {
    const keys = Object.keys(counts);
    if (keys.length <= MAX_SIGNATURES) return;
    for (const key of keys.slice(0, keys.length - MAX_SIGNATURES)) delete counts[key];
  };
  trim(state.toolCounts);
  trim(state.errorCounts);
  if (state.messageOrder.length > MAX_MESSAGES) {
    const drop = state.messageOrder.splice(0, state.messageOrder.length - MAX_MESSAGES);
    for (const id of drop) delete state.messageCosts[id];
  }
}

class StateStore {
  readonly directory: string;
  private readonly cache = new Map<string, SessionState>();
  private readonly now: () => number;

  constructor(directory: string, now: () => number) {
    this.directory = directory;
    this.now = now;
  }

  get(sessionId: string): SessionState {
    const cached = this.cache.get(sessionId);
    if (cached !== undefined) return cached;
    const path = sessionStatePath(this.directory, sessionId);
    let state: SessionState;
    try {
      state = reviveState(JSON.parse(readFileSync(path, "utf8")), sessionId, this.now());
    } catch {
      state = freshState(sessionId, this.now());
    }
    this.cache.set(sessionId, state);
    return state;
  }

  save(state: SessionState): void {
    state.updatedAt = this.now();
    pruneState(state);
    this.cache.set(state.sessionId, state);
    try {
      mkdirSync(this.directory, { recursive: true, mode: 0o700 });
      const path = sessionStatePath(this.directory, state.sessionId);
      const temporary = `${path}.tmp`;
      writeFileSync(temporary, `${JSON.stringify(state, null, 2)}\n`, { mode: 0o600 });
      renameSync(temporary, path);
    } catch {
      // A read-only home must not break the session. The in-memory state stays.
    }
  }
}

// ---------------------------------------------------------------------------
// Configuration and HTTP
// ---------------------------------------------------------------------------

export interface PluginConfig {
  readonly baseUrl: string | null;
  readonly key: string | null;
  readonly stateDir: string;
}

const POLICY_TTL_MS = 60_000;
const SOFT_CHECK_MS = 60_000;
const HTTP_TIMEOUT_MS = 3_000;

function envValue(
  env: Record<string, string | undefined>,
  names: ReadonlyArray<string>,
): string | null {
  for (const name of names) {
    const value = env[name];
    if (value !== undefined && value.trim() !== "") return value.trim();
  }
  return null;
}

function secretFromFile(path: string): string | null {
  try {
    if ((statSync(path).mode & 0o077) !== 0) return null;
    const value = readFileSync(path, "utf8").replace(/[\r\n\s]+$/, "");
    return value === "" ? null : value;
  } catch {
    return null;
  }
}

function defaultStateDir(env: Record<string, string | undefined>): string {
  const explicit = envValue(env, ["TAA_PLUGIN_STATE_DIR"]);
  if (explicit !== null) return explicit;
  const xdg = envValue(env, ["XDG_STATE_HOME"]);
  if (xdg !== null) return join(xdg, "team-ai-allowance", "opencode");
  return join(homedir(), ".local", "state", "team-ai-allowance", "opencode");
}

export function resolveConfig(
  env: Record<string, string | undefined>,
  overrides: { readonly stateDir?: string; readonly baseUrl?: string; readonly key?: string },
): PluginConfig {
  const baseUrl = overrides.baseUrl ?? envValue(env, ["TAA_BASE_URL", "TAA_URL"]);
  const keyFile = envValue(env, ["TAA_MEMBER_KEY_FILE", "TAA_KEY_FILE"]);
  const key =
    overrides.key ??
    (keyFile !== null ? secretFromFile(keyFile) : envValue(env, ["TAA_MEMBER_KEY", "TAA_KEY"]));
  return {
    baseUrl: baseUrl === null ? null : baseUrl.replace(/\/+$/, ""),
    key,
    stateDir: overrides.stateDir ?? defaultStateDir(env),
  };
}

