export const NOTICE_PREFIX = "Allowance: ";
export const BUDGET_BLOCK_PREFIX = "Session budget exhausted:";
export const UNATTENDED_BLOCK_PREFIX = "Unattended session paused:";
export const LOOP_BLOCK_PREFIX = "Loop paused:";

export type SessionEventKind =
  | "budget_warning"
  | "budget_stop"
  | "unattended_pause"
  | "loop_pause"
  | "soft_limit_notice"
  | "policy_fallback";

interface BudgetView {
  readonly spentUsd: number;
  readonly limitUsd: number;
  readonly ratio: number;
}

class Controller {
  private readonly client: PluginClientLike;
  private readonly config: PluginConfig;
  private readonly now: () => number;
  private readonly fetchImpl: typeof fetch;
  private readonly logger: { warn(message: string): void };
  private readonly store: StateStore;
  private readonly pending = new Set<Promise<unknown>>();
  private readonly policyRequests = new Map<string, Promise<SessionPolicy>>();
  private readonly warnedFailures = new Set<string>();
  /** Last tool-call timestamp per session; v2 has no human-message signal. */
  private readonly lastToolAt = new Map<string, number>();

  constructor(input: PluginInputLike, options: PluginOptions) {
    const env = options.env ?? process.env;
    this.client = input.client;
    this.now = options.now ?? (() => Date.now());
    this.config = resolveConfig(env, {
      ...(options.stateDir === undefined ? {} : { stateDir: options.stateDir }),
      ...(options.baseUrl === undefined ? {} : { baseUrl: options.baseUrl }),
      ...(options.key === undefined ? {} : { key: options.key }),
    });
    this.fetchImpl = options.fetchImpl ?? fetch;
    this.logger = options.logger ?? {
      warn: (message: string) => {
        try {
          process.stderr.write(`team-ai-allowance plugin: ${message}\n`);
        } catch {
          // stderr may be closed; never break the session for a log line.
        }
      },
    };
    this.store = new StateStore(this.config.stateDir, this.now);
  }

  hooks(): Hooks {
    return {
      event: async ({ event }) => {
        await this.guard("event", async () => {
          await this.onEvent(event);
        });
      },
      "chat.message": async (input, output) => {
        await this.guard("chat.message", async () => {
          await this.onChatMessage(input.sessionID, output.message, output.parts);
        });
      },
      "tool.execute.before": async (input, output) => {
        await this.guard("tool.execute.before", async () => {
          await this.beforeTool(input, output.args);
        });
      },
      "tool.execute.after": async (input, output) => {
        await this.guard("tool.execute.after", async () => {
          await this.afterTool(input, output);
        });
      },
    };
  }

  /** Await background posts; tests use this, the host never needs it. */
  async flush(): Promise<void> {
    while (this.pending.size > 0) {
      await Promise.allSettled([...this.pending]);
    }
  }

  state(sessionId: string): SessionState {
    return this.store.get(sessionId);
  }

  /**
   * v2 adapter hook (OpenCode ≥2 file plugins expose no human-message
   * signal). Marks session activity: a tool call after an idle gap longer
   * than the unattended window starts a fresh turn, exactly like a human
   * message would; otherwise lastHumanAt tracks the burst so the time rule
   * measures activity gaps instead of bricking long sessions.
   */
  async noteToolActivity(sessionId: string): Promise<void> {
    const state = this.store.get(sessionId);
    const policy = await this.ensurePolicy(sessionId, state);
    const working = isWorkingTime(policy.unattended.workingHours, this.now());
    const limits = working ? policy.unattended.working : policy.unattended.offHours;
    const now = this.now();
    const lastToolAt = this.lastToolAt.get(sessionId) ?? state.lastHumanAt;
    this.lastToolAt.set(sessionId, now);
    if (now - lastToolAt >= limits.maxMinutes * 60_000) {
      this.resetTurnState(state);
    } else {
      state.lastHumanAt = now;
      this.save(state);
    }
  }

  /**
   * v2 adapter hook: start a fresh turn (steps, loop and error counters
   * cleared, pause lifted). Called after an idle gap and after an abort has
   * stopped a paused run, so a resumed session is never bricked.
   */
  resetTurn(sessionId: string): void {
    this.resetTurnState(this.store.get(sessionId));
  }

  private resetTurnState(state: SessionState): void {
    state.lastHumanAt = this.now();
    state.stepsSinceHuman = 0;
    state.pause = null;
    for (const key of Object.keys(state.toolCounts)) delete state.toolCounts[key];
    for (const key of Object.keys(state.errorCounts)) delete state.errorCounts[key];
    this.save(state);
  }

  private async guard(name: string, body: () => Promise<void>): Promise<void> {
    try {
      await body();
    } catch (error) {
      if (error instanceof BlockedError) throw error;
      this.warnOnce(`${name}: ${error instanceof Error ? error.name : "unknown error"}`);
    }
  }

  private warnOnce(message: string): void {
    if (this.warnedFailures.has(message)) return;
    this.warnedFailures.add(message);
    this.logger.warn(message);
  }

  private save(state: SessionState): void {
    this.store.save(state);
  }

  private track(work: Promise<unknown>): void {
    this.pending.add(work);
    void work.finally(() => this.pending.delete(work)).catch(() => undefined);
  }

  // -- policy -------------------------------------------------------------

  private async ensurePolicy(sessionId: string, state: SessionState): Promise<SessionPolicy> {
    const now = this.now();
    if (state.lastPolicy !== null && now - state.lastPolicyFetchAt < POLICY_TTL_MS) {
      return state.lastPolicy;
    }
    const existing = this.policyRequests.get(sessionId);
    if (existing !== undefined) return existing;
    const request = this.refreshPolicy(state).finally(() => {
      this.policyRequests.delete(sessionId);
    });
    this.policyRequests.set(sessionId, request);
    return request;
  }

  private async refreshPolicy(state: SessionState): Promise<SessionPolicy> {
    try {
      const payload = await this.getJson("/api/me/session-policy");
      const policy = parseSessionPolicy(payload);
      state.lastPolicy = policy;
      state.lastPolicyFetchAt = this.now();
      state.policyFallbackPosted = false;
      this.save(state);
      return policy;
    } catch {
      // The dedicated route may not be deployed yet. Try the
      // member allowance, which carries the budget fields.
      try {
        const allowance = await this.getJson("/api/me");
        const policy = policyFromAllowance(allowance);
        state.lastPolicy = policy;
        state.lastPolicyFetchAt = this.now();
        state.policyFallbackPosted = false;
        this.save(state);
        return policy;
      } catch {
        const hadLastKnown = state.lastPolicy !== null;
        const fallback = state.lastPolicy ?? DEFAULT_SESSION_POLICY;
        state.lastPolicy = fallback;
        state.lastPolicyFetchAt = this.now();
        if (!state.policyFallbackPosted) {
          state.policyFallbackPosted = true;
          this.postEvent(state.sessionId, "policy_fallback", { hadLastKnown });
        }
        this.save(state);
        return fallback;
      }
    }
  }

  // -- event hook ---------------------------------------------------------

  private async onEvent(event: EventLike): Promise<void> {
    if (event.type !== "message.updated") return;
    const info = event.properties?.info;
    if (!isRecord(info) || info.role !== "assistant") return;
    if (typeof info.id !== "string" || typeof info.sessionID !== "string") return;
    const time = isRecord(info.time) ? info.time : {};
    if (finiteNumber(time.completed) === null) return;
    const cost = nonNegativeNumber(info.cost, 0);
    const message: AssistantMessageLike = {
      role: "assistant",
      id: info.id,
      sessionID: info.sessionID,
      time: { created: nonNegativeNumber(time.created, this.now()) },
      cost,
    };
    await this.accountMessage(message);
  }

  private async accountMessage(message: AssistantMessageLike): Promise<void> {
    const state = this.store.get(message.sessionID);
    const previous = state.messageCosts[message.id] ?? 0;
    const delta = (message.cost ?? 0) - previous;
    if (delta > 0) state.costUsd += delta;
    if (!Object.hasOwn(state.messageCosts, message.id)) state.messageOrder.push(message.id);
    state.messageCosts[message.id] = message.cost ?? 0;
    this.save(state);

    const policy = await this.ensurePolicy(message.sessionID, state);
    const budget = budgetView(state, policy);
    await this.fireBudgetNotices(state, policy, budget, message.sessionID);
  }

  private async fireBudgetNotices(
    state: SessionState,
    policy: SessionPolicy,
    budget: BudgetView,
    sessionId: string,
  ): Promise<void> {
    const thresholds = [...policy.budget.warnRatios].sort((left, right) => left - right);
    for (const threshold of thresholds) {
      if (budget.ratio < threshold || state.warnFired.includes(threshold)) continue;
      state.warnFired.push(threshold);
      this.save(state);
      const percent = Math.round(threshold * 100);
      await this.notice(
        sessionId,
        `Session budget: ${percent}% used (USD ${money(budget.spentUsd)} of USD ${money(budget.limitUsd)}).`,
      );
      this.postEvent(sessionId, "budget_warning", {
        threshold,
        spendUsd: round2(budget.spentUsd),
        limitUsd: round2(budget.limitUsd),
      });
    }

    if (budget.ratio >= policy.budget.stopRatio && !state.stopFired) {
      state.stopFired = true;
      this.save(state);
      await this.notice(sessionId, budgetBlockMessage(budget));
      this.postEvent(sessionId, "budget_stop", {
        spendUsd: round2(budget.spentUsd),
        limitUsd: round2(budget.limitUsd),
      });
      await this.abort(sessionId);
    }
  }

  // -- chat.message -------------------------------------------------------

  private async onChatMessage(
    sessionId: string,
    message: MessageLike,
    parts: ReadonlyArray<TextPartLike>,
  ): Promise<void> {
    if (!isHumanMessage(message, parts)) return;
    const state = this.store.get(sessionId);
    const now = this.now();
    state.lastHumanAt = now;
    state.stepsSinceHuman = 0;
    state.pause = null;
    for (const key of Object.keys(state.toolCounts)) delete state.toolCounts[key];
    for (const key of Object.keys(state.errorCounts)) delete state.errorCounts[key];
    this.save(state);
  }

  // -- tool hooks ---------------------------------------------------------

  private async beforeTool(input: ToolBeforeInput, args: unknown): Promise<void> {
    const state = this.store.get(input.sessionID);
    const policy = await this.ensurePolicy(input.sessionID, state);
    const now = this.now();

    if (state.pause !== null) {
      throw blockError(pauseMessage(state.pause, policy));
    }

    const budget = budgetView(state, policy);
    if (budget.ratio >= policy.budget.stopRatio) {
      if (!state.stopFired) {
        state.stopFired = true;
        this.save(state);
        await this.notice(input.sessionID, budgetBlockMessage(budget));
        this.postEvent(input.sessionID, "budget_stop", {
          spendUsd: round2(budget.spentUsd),
          limitUsd: round2(budget.limitUsd),
        });
        await this.abort(input.sessionID);
      }
      throw blockError(budgetBlockMessage(budget));
    }

    const working = isWorkingTime(policy.unattended.workingHours, now);
    const limits = working ? policy.unattended.working : policy.unattended.offHours;
    const elapsedMs = now - state.lastHumanAt;
    if (elapsedMs >= limits.maxMinutes * 60_000) {
      await this.pause(state, {
        kind: "unattended",
        reason: "time",
        at: now,
        detail: {
          elapsedMinutes: Math.floor(elapsedMs / 60_000),
          maxMinutes: limits.maxMinutes,
          workingHours: working,
        },
      });
      throw blockError(pauseMessage(state.pause, policy));
    }
    if (state.stepsSinceHuman >= limits.maxSteps) {
      await this.pause(state, {
        kind: "unattended",
        reason: "steps",
        at: now,
        detail: {
          steps: state.stepsSinceHuman,
          maxSteps: limits.maxSteps,
          workingHours: working,
        },
      });
      throw blockError(pauseMessage(state.pause, policy));
    }

    const signature = toolSignature(input.tool, args);
    const count = (state.toolCounts[signature] ?? 0) + 1;
    state.toolCounts[signature] = count;
    if (count >= policy.loop.sameToolArgs) {
      await this.pause(state, {
        kind: "loop",
        reason: "tool_args",
        at: now,
        detail: { tool: input.tool, count, limit: policy.loop.sameToolArgs },
      });
      throw blockError(pauseMessage(state.pause, policy));
    }

    state.stepsSinceHuman += 1;
    this.save(state);

    this.track(this.checkSoftLimit(input.sessionID, state, policy));
  }

  private async afterTool(input: ToolAfterInput, output: ToolAfterOutput): Promise<void> {
    const signature = toolErrorSignature(output);
    if (signature === null) return;
    const state = this.store.get(input.sessionID);
    const policy = await this.ensurePolicy(input.sessionID, state);
    const count = (state.errorCounts[signature] ?? 0) + 1;
    state.errorCounts[signature] = count;
    this.save(state);
    if (count >= policy.loop.sameError && state.pause === null) {
      await this.pause(state, {
        kind: "loop",
        reason: "error",
        at: this.now(),
        detail: { tool: input.tool, count, limit: policy.loop.sameError },
      });
    }
  }

  private async pause(
    state: SessionState,
    pause: PauseState & { readonly detail: Record<string, unknown> },
  ): Promise<void> {
    if (state.pause !== null) return;
    state.pause = { kind: pause.kind, reason: pause.reason, at: pause.at };
    this.save(state);
    this.track(this.notice(state.sessionId, pauseMessage(state.pause, null)));
    this.postEvent(
      state.sessionId,
      pause.kind === "unattended" ? "unattended_pause" : "loop_pause",
      pause.detail,
    );
    await this.abort(state.sessionId);
  }

  // -- soft limit ---------------------------------------------------------

  private async checkSoftLimit(
    sessionId: string,
    state: SessionState,
    policy: SessionPolicy,
  ): Promise<void> {
    if (state.softNoticeShown) return;
    const now = this.now();
    if (now - state.lastSoftCheckAt < SOFT_CHECK_MS) return;
    state.lastSoftCheckAt = now;
    this.save(state);
    let payload: unknown;
    try {
      payload = await this.getJson("/api/me");
    } catch {
      return;
    }
    if (!isRecord(payload)) return;
    const limits = isRecord(payload.limits) ? payload.limits : {};
    const limit =
      finiteNumber(payload.effectiveBudgetUsd) ??
      finiteNumber(limits.budgetUsd) ??
      policy.budget.limitUsd;
    const spend = finiteNumber(payload.spendUsd);
    if (limit === null || limit <= 0 || spend === null || spend < 0) return;
    const ratio = spend / limit;
    if (ratio < policy.softLimitRatio) return;
    const percent = Math.round(ratio * 100);
    state.softNoticeShown = true;
    this.save(state);
    await this.notice(sessionId, softLimitMessage(percent));
    this.postEvent(sessionId, "soft_limit_notice", {
      percent,
      ratio: round2(ratio),
      spendUsd: round2(spend),
      limitUsd: round2(limit),
    });
  }

  // -- actions ------------------------------------------------------------

  private async notice(sessionId: string, text: string): Promise<void> {
    try {
      await this.client.session.prompt({
        path: { id: sessionId },
        body: { noReply: true, parts: [{ type: "text", text }] },
      });
    } catch {
      try {
        await this.client.tui?.showToast?.({
          body: { message: text, variant: "warning", duration: 6000 },
        });
      } catch {
        this.warnOnce("notice: could not deliver a session notice");
      }
    }
  }

  private async abort(sessionId: string): Promise<void> {
    try {
      await this.client.session.abort({ path: { id: sessionId } });
    } catch {
      this.warnOnce("abort: could not abort the session");
    }
  }

  private postEvent(
    sessionId: string,
    kind: SessionEventKind,
    detail: Record<string, unknown>,
  ): void {
    if (this.config.baseUrl === null || this.config.key === null) return;
    const body = {
      kind,
      sessionId,
      at: new Date(this.now()).toISOString(),
      detail,
    };
    this.track(this.postJson("/api/me/session-events", body));
  }

  // -- HTTP ---------------------------------------------------------------

  private async getJson(path: string): Promise<unknown> {
    const response = await this.request("GET", path);
    return response.json();
  }

  private async postJson(path: string, body: unknown): Promise<void> {
    await this.request("POST", path, body);
  }

  private async request(method: string, path: string, body?: unknown): Promise<Response> {
    if (this.config.baseUrl === null || this.config.key === null) {
      throw new Error("control service is not configured");
    }
    let response: Response;
    try {
      response = await this.fetchImpl(`${this.config.baseUrl}${path}`, {
        method,
        headers: {
          authorization: `Bearer ${this.config.key}`,
          ...(body === undefined ? {} : { "content-type": "application/json" }),
        },
        ...(body === undefined ? {} : { body: JSON.stringify(body) }),
        signal: AbortSignal.timeout(HTTP_TIMEOUT_MS),
      });
    } catch {
      throw new Error("control service is unreachable");
    }
    if (!response.ok) throw new Error(`control service answered ${response.status}`);
    return response;
  }
}

// ---------------------------------------------------------------------------
// Messages and helpers
// ---------------------------------------------------------------------------

function budgetView(state: SessionState, policy: SessionPolicy): BudgetView {
  const spentUsd = policy.budget.spentUsd + state.costUsd;
  const limitUsd = policy.budget.limitUsd;
  const ratio = Number.isFinite(limitUsd) && limitUsd > 0 ? spentUsd / limitUsd : 0;
  return { spentUsd, limitUsd, ratio };
}

function money(value: number): string {
  if (!Number.isFinite(value)) return "unlimited";
  return value.toFixed(2);
}

function round2(value: number): number {
  return Math.round(value * 100) / 100;
}

export function softLimitMessage(percent: number): string {
  return `${NOTICE_PREFIX}${percent}% of today's budget used. If you need more for this task, call request_more_budget now, before it runs out.`;
}

export function budgetBlockMessage(budget: BudgetView): string {
  return `${BUDGET_BLOCK_PREFIX} USD ${money(budget.spentUsd)} of USD ${money(budget.limitUsd)} used. Ask your manager for more with the MCP request_more_budget tool, then continue.`;
}

export function pauseMessage(pause: PauseState | null, policy: SessionPolicy | null): string {
  if (pause === null) return `${UNATTENDED_BLOCK_PREFIX} send a new message to continue.`;
  if (pause.kind === "loop") {
    return `${LOOP_BLOCK_PREFIX} the same ${pause.reason === "error" ? "error" : "tool call"} repeated. Send a new message to continue.`;
  }
  const limits =
    policy === null
      ? null
      : isWorkingTime(policy.unattended.workingHours, pause.at)
        ? policy.unattended.working
        : policy.unattended.offHours;
  if (pause.reason === "steps") {
    const detail = limits === null ? "" : `${limits.maxSteps} steps without `;
    return `${UNATTENDED_BLOCK_PREFIX} ${detail}a human message. Send a new message to continue.`;
  }
  const detail = limits === null ? "" : `${limits.maxMinutes} minutes without `;
  return `${UNATTENDED_BLOCK_PREFIX} ${detail}a human message. Send a new message to continue.`;
}

/** True when a chat message came from the person, not from OpenCode itself. */
export function isHumanMessage(message: MessageLike, parts: ReadonlyArray<TextPartLike>): boolean {
  if (message.role !== undefined && message.role !== "user") return false;
  const texts = parts.filter((part) => part.type === "text");
  if (texts.length === 0) return parts.length > 0;
  if (texts.every((part) => part.synthetic === true)) return false;
  const text = texts.map((part) => part.text ?? "").join("");
  const ownNotice =
    text.startsWith(NOTICE_PREFIX) ||
    text.startsWith(BUDGET_BLOCK_PREFIX) ||
    text.startsWith(UNATTENDED_BLOCK_PREFIX) ||
    text.startsWith(LOOP_BLOCK_PREFIX);
  return !ownNotice;
}

/** Thrown inside `tool.execute.before`; OpenCode turns it into a failed tool call. */
export class BlockedError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "BlockedError";
  }
}

function blockError(message: string): BlockedError {
  return new BlockedError(message);
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

class AllowancePlugin {
  private readonly controller: Controller;

  constructor(input: PluginInputLike, options: PluginOptions) {
    this.controller = new Controller(input, options);
  }

  hooks(): Hooks {
    return this.controller.hooks();
  }

  /** v2 adapter hook: mark session activity (see Controller.noteToolActivity). */
  async noteToolActivity(sessionId: string): Promise<void> {
    await this.controller.noteToolActivity(sessionId);
  }

  /** v2 adapter hook: start a fresh turn (see Controller.resetTurn). */
  resetTurn(sessionId: string): void {
    this.controller.resetTurn(sessionId);
  }

  flush(): Promise<void> {
    return this.controller.flush();
  }

  state(sessionId: string): SessionState {
    return this.controller.state(sessionId);
  }
}

export function createPlugin(input: PluginInputLike, options: PluginOptions = {}): AllowancePlugin {
  return new AllowancePlugin(input, options);
}

/**
 * OpenCode server-plugin entry point (v1 Hooks shape, OpenCode 1.x).
 * The module is loaded from a managed config; returning the `Hooks`
 * object is all OpenCode needs.
 */
export const server = async (input: PluginInputLike, options: PluginOptions = {}): Promise<Hooks> =>
  createPlugin(input, options).hooks();

// ---------------------------------------------------------------------------
// OpenCode v2 file-plugin entry (verified against OpenCode 2.1.3)
// ---------------------------------------------------------------------------
//
// v2 loads local files only from the plugin directories (`~/.config/opencode
// /plugins/`, `.opencode/plugins/`; the `plugin` config key is npm-only) and
// requires the default export to be a definition `{ id, setup }`. Tool
// interception moved to `ctx.tool.hook("execute.before"/"execute.after")`;
// there is no human-message signal, so the adapter drives the turn
// boundaries itself (see Controller.noteToolActivity / resetTurn).

/** Minimal structural surface of the v2 plugin context this adapter uses. */
export interface V2ToolBeforeInput {
  readonly tool: string;
  readonly sessionID: string;
  readonly agent?: string;
  readonly messageID?: string;
  readonly id: string;
  readonly input: unknown;
}

export interface V2ToolAfterInput extends V2ToolBeforeInput {
  readonly status?: string;
  readonly result?: unknown;
}

export interface V2SessionContext {
  interrupt(input: { sessionID: string }): Promise<unknown>;
}

export interface V2ToolContext {
  hook(
    name: string,
    callback: (input: V2ToolAfterInput) => Promise<unknown> | unknown,
  ): Promise<unknown>;
}

export interface V2PluginContext {
  readonly tool: V2ToolContext;
  readonly session: V2SessionContext;
  readonly worktree?: string;
}

export interface V2PluginDefinition {
  readonly id: string;
  readonly setup: (context: V2PluginContext) => Promise<void> | void;
}

function v2TextOf(result: unknown): string {
  if (typeof result === "string") return result;
  if (!isRecord(result)) return "";
  const output = result.output;
  if (typeof output === "string") return output;
  if (isRecord(output) && typeof output.output === "string") return output.output;
  const content = result.content;
  if (Array.isArray(content)) {
    return content
      .map((part) => (isRecord(part) && typeof part.text === "string" ? part.text : ""))
      .join("\n");
  }
  const error = result.error;
  if (isRecord(error) && typeof error.message === "string") return error.message;
  return "";
}

function v2Client(
  ctx: V2PluginContext,
  support: {
    plugin: {
      current: {
        state(sessionId: string): { pause: unknown };
      } | null;
    };
  },
): PluginClientLike {
  return {
    session: {
      prompt: async () => {
        // v2 exposes no verified in-session notice shape; block errors
        // thrown below already carry the message to the model.
        throw new Error("v2 adapter: in-session prompt injection is not wired");
      },
      abort: async (input: SessionAbortInput) => {
        // A pause already set means this abort comes from pause(): defer it.
        // The adapter interrupts on the second consecutive pause block, so
        // the first block's message stays visible to the model. A budget
        // stop (no pause set) interrupts immediately.
        const plugin = support.plugin.current;
        if (plugin === null || plugin.state(input.path.id).pause === null) {
          await ctx.session.interrupt({ sessionID: input.path.id });
        }
      },
    },
  };
}

/** v2 setup, exported for tests (the loader calls it with the live context). */
export async function setupV2Plugin(
  ctx: V2PluginContext,
  options: PluginOptions = {},
): Promise<void> {
  const support: {
    plugin: {
      current: {
        state(sessionId: string): { pause: unknown };
      } | null;
    };
  } = { plugin: { current: null } };
  const plugin = createPlugin(
    {
      client: v2Client(ctx, support),
      ...(ctx.worktree === undefined ? {} : { worktree: ctx.worktree }),
    },
    options,
  );
  support.plugin.current = plugin;
  const consecutivePause = new Map<string, boolean>();
  const hooks = plugin.hooks();
  const beforeTool = hooks["tool.execute.before"];
  const afterTool = hooks["tool.execute.after"];
  if (beforeTool === undefined || afterTool === undefined) {
    throw new Error("v2 adapter: the controller hooks are unavailable");
  }
  await ctx.tool.hook("execute.before", async (input) => {
    await plugin.noteToolActivity(input.sessionID);
    try {
      await beforeTool(
        { tool: input.tool, sessionID: input.sessionID, callID: input.id },
        { args: input.input },
      );
      consecutivePause.delete(input.sessionID);
    } catch (error) {
      // A pause block carries the rule text to the model via the thrown
      // error. The first block only shows the message; when the runaway
      // persists into the next tool call, interrupt the session, then clear
      // the pause so a resumed session keeps working. Fail closed: when the
      // interrupt itself fails the pause stays set and every tool stays
      // blocked.
      if (plugin.state(input.sessionID).pause !== null) {
        if (consecutivePause.get(input.sessionID) === true) {
          try {
            await ctx.session.interrupt({ sessionID: input.sessionID });
            plugin.resetTurn(input.sessionID);
            consecutivePause.delete(input.sessionID);
          } catch {
            // Pause stays set; the session is stopped, not silently unguarded.
          }
        } else {
          consecutivePause.set(input.sessionID, true);
        }
      }
      throw error;
    }
  });
  await ctx.tool.hook("execute.after", async (input) => {
    const result = input.result;
    const text = v2TextOf(result);
    const metadata: Record<string, unknown> = {
      ...(isRecord(result) && isRecord(result.metadata)
        ? (result.metadata as Record<string, unknown>)
        : {}),
      status: input.status,
    };
    if (isRecord(result) && result.error !== undefined) metadata.error = result.error;
    await afterTool(
      {
        tool: input.tool,
        sessionID: input.sessionID,
        callID: input.id,
        args: input.input,
      },
      { title: input.tool, output: text, metadata },
    );
  });
}

/**
 * The file-plugin definition OpenCode ≥2 loads. Keep the module free of
 * runtime imports (build.ts enforces this): only Node built-ins are used.
 */
const teamAiAllowanceV2: V2PluginDefinition = {
  id: "team-ai-allowance",
  setup: (ctx) => setupV2Plugin(ctx),
};

export default teamAiAllowanceV2;
